SELECT * FROM TUNE_BI_DB.GOLD.VW_AS_AT;
SELECT * FROM TUNE_BI_DB.GOLD.MART_REGISTRY;
SELECT * FROM TUNE_BI_DB.GOLD.DERIVED_METRIC WHERE MART_NAME='GI_ENTERPRISE_WIDE_MART';
SELECT COUNT(*) ROW_COUNT,COUNT(DISTINCT CUSTOMER_ID) CUSTOMERS, MIN(SNAPSHOT_DATE) SNAPSHOT_MIN,MAX(SNAPSHOT_DATE) SNAPSHOT_MAX,MIN(NEXT_RENEWAL_MONTH) RENEWAL_MIN,MAX(NEXT_RENEWAL_MONTH) RENEWAL_MAX FROM TUNE_BI_DB.GOLD.CUSTOMER_360_WIDE_MART;
SELECT COUNT(*) ROW_COUNT,COUNT(DISTINCT CUSTOMER_ID) CUSTOMERS,COUNT_IF(NEXT_RENEWAL_MONTH IS NULL OR LIFETIME_VALUE IS NULL OR RETENTION_RISK_SCORE IS NULL OR PREFERRED_CHANNEL IS NULL) MISSING FROM TUNE_BI_DB.GOLD.CUSTOMER_360_WIDE_MART WHERE HOLDS_MOTOR='Yes' AND HOLDS_TRAVEL='No' AND NEXT_BEST_PRODUCT='Travel' AND MARKETING_CONSENT='Yes';
SELECT RETENTION_RISK_BAND,LIFETIME_VALUE_BAND,PREFERRED_CHANNEL,COUNT(*) N FROM TUNE_BI_DB.GOLD.CUSTOMER_360_WIDE_MART GROUP BY ALL;
SELECT ACCOUNTING_MONTH,LINE_OF_BUSINESS,COUNT(*) N,SUM(GROSS_WRITTEN_PREMIUM) GWP FROM TUNE_BI_DB.GOLD.GI_ENTERPRISE_WIDE_MART GROUP BY ALL ORDER BY 1,2;
SELECT ACCOUNTING_MONTH,LINE_OF_BUSINESS,COUNT(*) N,SUM(PLAN_GROSS_WRITTEN_PREMIUM) GWP FROM TUNE_BI_DB.GOLD.GI_PLAN_MONTHLY GROUP BY ALL ORDER BY 1,2;
SELECT COUNT(*) DUPLICATE_KEYS FROM (SELECT ACCOUNTING_MONTH,ENTITY_CODE,LINE_OF_BUSINESS,DISTRIBUTION_CHANNEL,COUNT(*) N FROM TUNE_BI_DB.GOLD.GI_PLAN_MONTHLY GROUP BY ALL HAVING N>1);
SHOW STREAMLITS IN DATABASE TUNE_BI_DB;
SELECT AI_COMPLETE('llama3.3-70b','Reply with exactly: Available') AS CORTEX_PROBE;


